INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('a6e039e8-c064-42f6-bf2e-0fd050f74b5b', (SELECT id FROM recipe_db.recipe_version WHERE public_id = 'd4369143-a915-4de9-9dc8-679c8ab54753'), 1, 'Chuẩn bị nguyên liệu & dụng cụ', 'Đo lường định lượng các nguyên vật liệu chính xác theo bảng thành phần.', 60, NULL, 'Cân tiểu ly, ca đong', NULL, 'Đầy đủ nguyên liệu theo định lượng');
