INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('8d043dae-f091-57ca-a257-b1ab7e3e0cff', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '81dd3bb1-09c7-4637-9cbd-c4872c167579'), 1, 'Chuẩn bị dụng cụ và nguyên liệu', 'Rửa tay, vệ sinh ly 350 ml, ca đong và muỗng khuấy. Cân đong sẵn 60 ml espresso, 30 ml sữa đặc và 150 g đá viên.', 120, NULL, 'Cân tiểu ly, ca đong, ly 350 ml, muỗng khuấy', 'Dùng dụng cụ sạch, khô; bảo quản lạnh sữa đặc đã mở nắp.', 'Nguyên liệu đủ định lượng, dụng cụ sạch và khô.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('17ac75d8-2fd4-598d-b50f-327c8488b764', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '81dd3bb1-09c7-4637-9cbd-c4872c167579'), 2, 'Chiết xuất espresso', 'Chiết 60 ml espresso bằng máy pha, thời gian chiết khoảng 25–30 giây.', 30, 93, 'Máy pha espresso, ly đong', 'Cẩn thận khi thao tác với nước và cà phê nóng.', 'Espresso có lớp crema vàng nâu phủ mặt.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('f6131a65-7360-5810-a4da-5cb4083e2f1d', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '81dd3bb1-09c7-4637-9cbd-c4872c167579'), 3, 'Hòa sữa đặc với espresso', 'Rót 30 ml sữa đặc vào ca, đổ espresso nóng vào và khuấy khoảng 15 giây đến khi tan đều.', 45, 75, 'Ca pha, muỗng khuấy', 'Hỗn hợp còn nóng; không để sữa đặc bám đáy ca.', 'Hỗn hợp đồng nhất, không còn sữa đặc vón dưới đáy.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('a28ce23e-33b8-5281-9f5b-25b749cbd47f', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '81dd3bb1-09c7-4637-9cbd-c4872c167579'), 4, 'Cho đá vào ly', 'Cho 150 g đá viên sạch vào ly 350 ml, đá phủ khoảng 3/4 ly.', 20, NULL, 'Ly 350 ml, muỗng xúc đá', 'Dùng đá làm từ nước lọc, sạch.', 'Đá đầy khoảng 3/4 ly, không lẫn đá vụn bẩn.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('401cb313-7ab9-5497-98d5-ad1cef38727b', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '81dd3bb1-09c7-4637-9cbd-c4872c167579'), 5, 'Rót cà phê lên đá', 'Rót từ từ hỗn hợp cà phê sữa lên đá và khuấy nhẹ 3–4 vòng cho lạnh đều.', 30, NULL, 'Muỗng khuấy', NULL, 'Đồ uống lạnh đều, không đóng cặn.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('dbc46c97-f0df-5a3f-9def-f747c0214de1', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '81dd3bb1-09c7-4637-9cbd-c4872c167579'), 6, 'Kiểm tra và phục vụ', 'Nếm thử, lau sạch thành ly và phục vụ ngay kèm ống hút; không để đồ uống ở nhiệt độ phòng quá 2 phút.', 30, NULL, 'Khăn lau, ống hút', 'Không để đồ uống ở nhiệt độ phòng quá lâu.', 'Thành phẩm màu nâu đậm, vị ngọt béo cân bằng, trình bày sạch.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('d74fa42b-26bb-500f-b0ff-bd2a043dfde4', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '101b4143-fe92-4fca-98bd-6f5606f5196c'), 1, 'Chuẩn bị dụng cụ và nguyên liệu', 'Rửa tay, vệ sinh ly 400 ml, ca đong và muỗng khuấy. Cân đong 40 ml espresso, 140 ml sữa tươi lạnh, 20 ml siro caramel và 150 g đá viên.', 120, NULL, 'Cân tiểu ly, ca đong, ly 400 ml, muỗng khuấy', 'Dùng dụng cụ sạch; giữ sữa tươi trong tủ mát đến khi sử dụng.', 'Nguyên liệu đủ định lượng, sữa tươi còn lạnh.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('40c5278e-60ba-5d8b-bb6b-d05bfcda4e29', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '101b4143-fe92-4fca-98bd-6f5606f5196c'), 2, 'Chiết xuất espresso', 'Chiết 40 ml espresso bằng máy pha, thời gian chiết khoảng 25–30 giây.', 30, 93, 'Máy pha espresso, ly đong', 'Cẩn thận khi thao tác với nước và cà phê nóng.', 'Espresso có lớp crema mịn, không chảy quá nhanh.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('edfd43f8-a7ea-589b-963f-fb372fc19367', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '101b4143-fe92-4fca-98bd-6f5606f5196c'), 3, 'Hòa siro caramel với sữa tươi', 'Rót 20 ml siro caramel vào 140 ml sữa tươi lạnh, khuấy khoảng 20 giây đến khi siro tan đều.', 40, 5, 'Ca đong, muỗng khuấy', 'Dùng sữa tươi còn hạn; sữa chứa chất gây dị ứng.', 'Hỗn hợp sữa caramel đồng màu, không còn vệt siro dưới đáy.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('20ce787d-26a5-5640-9659-d33fbbdd9d9c', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '101b4143-fe92-4fca-98bd-6f5606f5196c'), 4, 'Cho đá vào ly', 'Cho 150 g đá viên vào ly 400 ml, đá phủ khoảng 2/3 ly.', 20, NULL, 'Ly 400 ml, muỗng xúc đá', 'Dùng đá làm từ nước lọc, sạch.', 'Đá đầy khoảng 2/3 ly.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('77b51d91-3891-52a6-b14b-818b86d59f7e', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '101b4143-fe92-4fca-98bd-6f5606f5196c'), 5, 'Rót sữa caramel lên đá', 'Rót chậm hỗn hợp sữa caramel lên đá, chừa khoảng 1/4 ly cho espresso.', 30, NULL, NULL, NULL, 'Mực sữa cách miệng ly khoảng 1/4 ly.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('c3c40c98-1422-58c4-a8f2-918c0f7aec0c', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '101b4143-fe92-4fca-98bd-6f5606f5196c'), 6, 'Thêm espresso và phục vụ', 'Rót espresso chậm theo thành muỗng để tạo lớp màu phân tầng, lau sạch thành ly và phục vụ ngay.', 40, NULL, 'Muỗng rót, khăn lau', 'Espresso còn nóng khi rót.', 'Thấy rõ lớp espresso nâu phía trên sữa caramel, trình bày sạch.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('18416704-0b88-5775-96a8-1022a82969c4', (SELECT id FROM recipe_db.recipe_version WHERE public_id = 'bdb60ef3-c0ce-402e-a2dc-e469b8a2d349'), 1, 'Chuẩn bị dụng cụ và nguyên liệu', 'Rửa tay, vệ sinh ly và ca đong. Cân đong 5 g trà lài, 180 ml nước lọc, 25 ml siro vải, 40 g vải ngâm và 150 g đá viên.', 120, NULL, 'Cân tiểu ly, ca đong, ly 400 ml', 'Dùng dụng cụ sạch; vải ngâm dùng từ hộp đã mở trong ngày.', 'Nguyên liệu đủ định lượng, dụng cụ sạch.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('7772edec-8200-502c-98a0-2e5dbb85017d', (SELECT id FROM recipe_db.recipe_version WHERE public_id = 'bdb60ef3-c0ce-402e-a2dc-e469b8a2d349'), 2, 'Ủ trà lài', 'Cho 5 g trà lài vào ấm, rót 180 ml nước 85°C và ủ 4 phút.', 240, 85, 'Ấm ủ trà, đồng hồ bấm giờ', 'Cẩn thận khi rót nước nóng.', 'Nước trà vàng nhạt, thơm hoa lài, không chát.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('f6018f82-0ebb-56a4-b9e6-dfc74bf83370', (SELECT id FROM recipe_db.recipe_version WHERE public_id = 'bdb60ef3-c0ce-402e-a2dc-e469b8a2d349'), 3, 'Lọc bã và làm nguội nhanh', 'Lọc bỏ bã trà, để trà nguội khoảng 2 phút hoặc đặt ca trà vào chậu nước đá.', 120, NULL, 'Rây lọc, ca đong', 'Đậy kín trà để giữ hương.', 'Trà còn ấm nhẹ, không còn bã.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('92490d69-5031-57e9-b561-8d3bfcec8e88', (SELECT id FROM recipe_db.recipe_version WHERE public_id = 'bdb60ef3-c0ce-402e-a2dc-e469b8a2d349'), 4, 'Hòa siro vải', 'Cho 25 ml siro vải vào trà và khuấy khoảng 10 giây đến khi tan đều.', 30, NULL, 'Muỗng khuấy', NULL, 'Trà đồng màu, vị ngọt nhẹ, thơm vải.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('caca3ba9-4b92-5338-ba6c-1e9531099462', (SELECT id FROM recipe_db.recipe_version WHERE public_id = 'bdb60ef3-c0ce-402e-a2dc-e469b8a2d349'), 5, 'Lắp ly', 'Cho 40 g vải ngâm vào ly rồi thêm 150 g đá viên.', 30, NULL, 'Ly 400 ml, muỗng xúc đá', 'Dùng đá làm từ nước lọc, sạch.', 'Vải phân bố đều dưới đáy ly, đá đầy khoảng 2/3 ly.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('b9370580-7026-5a04-879b-ddc0d5c2ceb7', (SELECT id FROM recipe_db.recipe_version WHERE public_id = 'bdb60ef3-c0ce-402e-a2dc-e469b8a2d349'), 6, 'Rót trà và hoàn thiện', 'Rót trà vải lên đá, khuấy nhẹ 2–3 vòng, trang trí thêm 1 múi vải và phục vụ ngay.', 30, NULL, 'Muỗng khuấy, ống hút', 'Không để đồ uống ở nhiệt độ phòng quá lâu.', 'Thành phẩm trong, màu vàng nhạt, thơm hoa lài và vải.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('8b7bdbec-baf6-5f1f-a2a3-149fa2a38102', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '83a48647-fa85-4bac-b6c9-9563428f53d1'), 1, 'Chuẩn bị dụng cụ và nguyên liệu', 'Rửa tay, vệ sinh ly và ca đong. Cân đong 5 g trà đen, 180 ml nước lọc, 15 ml nước cốt chanh, 20 ml mật ong và 150 g đá viên.', 120, NULL, 'Cân tiểu ly, ca đong, ly 400 ml', 'Dùng dụng cụ sạch, khô; dùng nước cốt chanh còn hạn.', 'Nguyên liệu đủ định lượng, dụng cụ sạch.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('2ce714b0-f4a6-51dc-b0c2-81d2507d34bc', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '83a48647-fa85-4bac-b6c9-9563428f53d1'), 2, 'Ủ trà đen', 'Cho 5 g trà đen vào ấm, rót 180 ml nước 95°C và ủ 4 phút.', 240, 95, 'Ấm ủ trà, đồng hồ bấm giờ', 'Cẩn thận khi rót nước sôi.', 'Nước trà màu đỏ hổ phách, thơm, không đắng gắt.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('1d7b027f-5511-59f9-bda1-916233bfc11d', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '83a48647-fa85-4bac-b6c9-9563428f53d1'), 3, 'Lọc bã và để trà ấm', 'Lọc bỏ bã trà, để trà nguội đến khoảng 60°C trước khi cho mật ong.', 120, 60, 'Rây lọc, nhiệt kế thực phẩm', 'Không cho mật ong vào trà đang sôi.', 'Nhiệt kế đo trà ở khoảng 60°C.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('a460d480-fa6f-5f3e-9196-d90ab50de8a6', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '83a48647-fa85-4bac-b6c9-9563428f53d1'), 4, 'Hòa mật ong', 'Cho 20 ml mật ong vào trà ấm và khuấy khoảng 15 giây đến khi tan hoàn toàn.', 30, 56, 'Muỗng khuấy', 'Mật ong có thể gây dị ứng với một số người.', 'Mật ong tan hết, không đọng dưới đáy ca.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('b9f3434d-9ee1-5742-a99e-6a43d58ca3cc', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '83a48647-fa85-4bac-b6c9-9563428f53d1'), 5, 'Thêm nước cốt chanh', 'Cho 15 ml nước cốt chanh vào hỗn hợp, khuấy đều và nếm thử độ chua ngọt.', 30, NULL, 'Ca đong, muỗng khuấy', NULL, 'Vị chua ngọt cân bằng, không gắt.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('8f7f70cf-fd32-544a-852b-aa4300157894', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '83a48647-fa85-4bac-b6c9-9563428f53d1'), 6, 'Rót vào ly đá và phục vụ', 'Cho 150 g đá viên vào ly, rót trà chanh mật ong lên đá, trang trí lát chanh và phục vụ ngay.', 30, NULL, 'Ly 400 ml, muỗng xúc đá', 'Không để đồ uống ở nhiệt độ phòng quá lâu.', 'Thành phẩm trong, màu hổ phách, trình bày sạch.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('8ed15c61-9b90-538d-8912-d85736acdef9', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '6a948d92-7fb1-4209-b123-c46d7f15331d'), 1, 'Chuẩn bị dụng cụ và nguyên liệu', 'Rửa tay, vệ sinh ly, ca đong và muỗng. Cân đong 6 g trà đen, 160 ml nước lọc, 20 g bột sữa, 20 ml đường nước, 50 g trân châu đen đã nấu chín và 120 g đá viên.', 180, NULL, 'Cân tiểu ly, ca đong, ly 500 ml', 'Dùng dụng cụ sạch; trân châu chỉ dùng trong ngày đã nấu.', 'Nguyên liệu đủ định lượng, trân châu còn mềm.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('b0b30c15-ada1-51d4-9f2b-6f163a8cb106', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '6a948d92-7fb1-4209-b123-c46d7f15331d'), 2, 'Ủ trà đen', 'Cho 6 g trà đen vào ấm, rót 160 ml nước 95°C và ủ 4 phút.', 240, 95, 'Ấm ủ trà, đồng hồ bấm giờ', 'Cẩn thận khi rót nước sôi.', 'Nước trà màu đỏ đậm, thơm, không đắng gắt.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('40386bf4-bdef-55d1-8084-de136c4907fe', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '6a948d92-7fb1-4209-b123-c46d7f15331d'), 3, 'Lọc bã và hòa bột sữa', 'Lọc bỏ bã trà, để trà ấm khoảng 70°C, cho 20 g bột sữa vào và khuấy khoảng 30 giây.', 60, 70, 'Rây lọc, muỗng khuấy', 'Bột sữa chứa sữa; không phù hợp người dị ứng đạm sữa.', 'Bột sữa tan hết, không vón cục.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('337027f7-8737-5ba7-8277-8641260d3caf', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '6a948d92-7fb1-4209-b123-c46d7f15331d'), 4, 'Thêm đường nước', 'Cho 20 ml đường nước vào trà sữa, khuấy đều rồi nếm thử độ ngọt.', 30, NULL, 'Ca đong, muỗng khuấy', NULL, 'Trà sữa đồng nhất, vị ngọt vừa phải.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('9303e40c-48a3-5bc6-9d49-ad3d5ab3bf4c', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '6a948d92-7fb1-4209-b123-c46d7f15331d'), 5, 'Lắp ly', 'Cho 50 g trân châu đen vào đáy ly 500 ml, thêm 120 g đá viên.', 30, NULL, 'Ly 500 ml, muỗng xúc', 'Dùng đá làm từ nước lọc, sạch.', 'Trân châu nằm gọn dưới đáy, đá phủ đều phía trên.');
INSERT INTO recipe_db.recipe_step (public_id, recipe_version_id, sort_order, title, description, duration_seconds, temperature_celsius, equipment, safety_note, completion_criteria) VALUES ('eeffab6b-c07d-56e1-8389-2cc2b65a3d52', (SELECT id FROM recipe_db.recipe_version WHERE public_id = '6a948d92-7fb1-4209-b123-c46d7f15331d'), 6, 'Rót trà sữa và phục vụ', 'Rót trà sữa lên đá, khuấy nhẹ 2–3 vòng, lau sạch thành ly và phục vụ kèm ống hút lớn.', 30, NULL, 'Muỗng khuấy, ống hút lớn', 'Không để đồ uống ở nhiệt độ phòng quá lâu.', 'Trà sữa màu nâu kem, trân châu hút được qua ống hút.');
